"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronDown, TrendingUp, TrendingDown, Minus } from "lucide-react";
import { cn } from "@/lib/utils";
import { ShareholdingPieChart } from "../charts/ShareholdingPieChart";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

// --- Data Structures ---
interface Shareholder {
  NAME: string;
  PERCENTAGE: number;
}
interface HistoryEntry {
  date: string;
  percentage: number;
  num_of_shares: number;
}
export interface ShareholdingDetailsData {
  interpretation: string;
  pieChartData: { name: string; value: number }[];
  categories: { [key: string]: Shareholder[] };
  history: { [key: string]: HistoryEntry[] };
  takeaways: string[];
}

// --- Sub-Components ---
const ShareholderHistoryRow = ({
  name,
  history,
}: {
  name: string;
  history: HistoryEntry[];
}) => {
  const [isOpen, setIsOpen] = useState(false);

  const getChangeIcon = (current: number, previous?: number) => {
    if (previous === undefined || current === previous)
      return <Minus size={12} className="text-gray-500" />;
    if (current > previous)
      return <TrendingUp size={12} className="text-green-500" />;
    return <TrendingDown size={12} className="text-red-500" />;
  };

  return (
    <>
      <TableRow
        onClick={() => setIsOpen(!isOpen)}
        className="cursor-pointer hover:bg-element-bg"
      >
        <TableCell className="font-medium text-text-primary">{name}</TableCell>
        <TableCell className="text-right text-text-secondary">
          {history[0]?.percentage.toFixed(2)}%
        </TableCell>
        <TableCell className="text-right">
          <ChevronDown
            size={16}
            className={cn("transition-transform", { "rotate-180": isOpen })}
          />
        </TableCell>
      </TableRow>
      {isOpen && (
        <TableRow>
          <TableCell colSpan={3} className="p-0">
            <div className="bg-background p-2">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Date</TableHead>
                    <TableHead className="text-right">Shares</TableHead>
                    <TableHead className="text-right">% Change</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {history.map((entry, index) => (
                    <TableRow key={index}>
                      <TableCell>{entry.date}</TableCell>
                      <TableCell className="text-right">
                        {(entry.num_of_shares / 10000000).toFixed(2)} Cr
                      </TableCell>
                      <TableCell className="flex justify-end items-center gap-1">
                        {entry.percentage.toFixed(2)}%
                        {getChangeIcon(
                          entry.percentage,
                          history[index + 1]?.percentage
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </TableCell>
        </TableRow>
      )}
    </>
  );
};

// --- Main Component ---
export function ShareholdingDetailsCard({
  data,
}: {
  title: string;
  data: ShareholdingDetailsData;
}) {
  const mainCategories = Object.entries(data.categories).filter(
    ([_, shareholders]) => shareholders.length > 0
  );

  return (
    <div className="w-full text-sm">
      <p className="text-text-secondary mb-4">{data.interpretation}</p>

      <ShareholdingPieChart
        data={data.pieChartData}
        title="Ownership Summary"
        description="Breakdown of major shareholder categories."
      />

      <div className="mt-6">
        <Accordion type="multiple" className="w-full">
          {mainCategories.map(([categoryName, shareholders]) => {
            const totalPercent = shareholders.reduce(
              (sum, s) => sum + s.PERCENTAGE,
              0
            );
            return (
              <AccordionItem value={categoryName} key={categoryName}>
                <AccordionTrigger>
                  <div className="flex justify-between w-full pr-2">
                    <span>{categoryName}</span>
                    <span className="text-text-secondary">
                      {totalPercent.toFixed(2)}%
                    </span>
                  </div>
                </AccordionTrigger>
                <AccordionContent>
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Shareholder Name</TableHead>
                        <TableHead className="text-right">% Holding</TableHead>
                        <TableHead className="w-[40px]"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {shareholders.map((sh) => (
                        <ShareholderHistoryRow
                          key={sh.NAME}
                          name={sh.NAME}
                          history={data.history[sh.NAME] || []}
                        />
                      ))}
                    </TableBody>
                  </Table>
                </AccordionContent>
              </AccordionItem>
            );
          })}
        </Accordion>
      </div>

      <div className="mt-8">
        <h3 className="text-base font-semibold text-text-primary mb-2">
          Key Takeaways
        </h3>
        <ul className="space-y-2 text-text-secondary list-disc pl-5">
          {data.takeaways.map((item, i) => (
            <li key={i}>{item}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}
